      .set(updates)
      .where(eq(portfolioHoldings.id, id))
      .returning();
    return updatedHolding || undefined;
  }

  async deleteHolding(id: string): Promise<boolean> {
    const result = await db.delete(portfolioHoldings)
      .where(eq(portfolioHoldings.id, id))
      .returning();
