        currentPrice: parseFloat(stock.currentPrice),
        previousClose: parseFloat(stock.previousClose),
        changePercent: parseFloat(stock.changePercent),
        volume: stock.volume,
        marketCap: stock.marketCap ? parseFloat(stock.marketCap) : undefined
